import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"Explanation","description":"","frontmatter":{},"headers":[],"relativePath":"kernel/explanation/index.md","filePath":"vendored/kernel/explanation/index.md"}`),a={name:`kernel/explanation/index.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to “Explanation”">​</a></h1><h2 id="why-this-crate-exists" tabindex="-1">Why this crate exists <a class="header-anchor" href="#why-this-crate-exists" aria-label="Permalink to “Why this crate exists”">​</a></h2><p>Everything above the kernel has to agree on what a language <em>is</em> and what a value <em>is</em>; the kernel is that agreement and nothing else. It was extracted from the <code>host</code> workspace (ADR-0128) so a consumer can pin the substrate without pulling the whole host, and it depends only on <code>hnl-engine</code> — which is why the dependency arrows all point downwards.</p><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to “Where it sits”">​</a></h2><p>This crate is the substrate layer under the <code>engine-*</code>, <code>kit-*</code> and <code>host-*</code> families. Engines, kits and hosts reach it through the kit&#39;s operation slot, so the engine can be swapped without touching a language definition.</p><p>See the <a href="/docs/kernel/reference/">reference</a> for the API and the <a href="/docs/kernel/how-to/">how-to guides</a> for tasks.</p>`,6)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};